def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Endgame logic for the final three rounds
    if n >= 97:
        if n == 97:
            return 'D'
        if n == 98:
            return 'D' if opp[-1] == 'D' else 'C'
        if n == 99:
            return 'D'

    # Compute retaliation rate: how often opponent defects after we defect
    retal_count = 0
    my_def_rounds = 0
    for i in range(n - 1):
        if me[i] == 'D':
            my_def_rounds += 1
            if opp[i + 1] == 'D':
                retal_count += 1
    retal_rate = retal_count / my_def_rounds if my_def_rounds > 0 else 0.0

    recent_len = min(10, n)
    recent = opp[n - recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_len

    total_c = sum(1 for a in opp if a == 'C')
    total_ratio = total_c / n

    # Detect likely randomness / always-defect
    if n >= 6:
        last6 = opp[-6:]
        if all(a == 'D' for a in last6):
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if all(a == 'C' for a in last6):
            # Proactive probe only if opponent seems forgiving
            if retal_rate <= 0.2 and n % 20 == 0 and n < 90:
                return 'D'
            return 'C'

    # Tit-for-tat with forgiveness and probing
    if n >= 2:
        if opp[-1] == 'D' and me[-1] == 'C':
            if recent_ratio > 0.6:
                if rng.random() < 0.7:
                    return 'C'
                return 'D'
            else:
                if rng.random() < 0.15:
                    return 'C'
                return 'D'
        if opp[-1] == 'D' and me[-1] == 'D':
            if n % 7 == 0 or recent_ratio > 0.35:
                return 'C'
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if opp[-1] == 'C':
            if len(history) >= 3:
                last3 = opp[-3:]
                if last3 == ['C', 'C', 'D'] and me[-1] == 'C':
                    return 'D'
            return 'C'

    return 'C'
